public static Object inv(Method method, Object target, Object ... arguments) {
        try {
            java.lang.invoke.MethodHandles.Lookup lookup = java.lang.invoke.MethodHandles.privateLookupIn(method.getDeclaringClass(), java.lang.invoke.MethodHandles.lookup());
